const interestOptions = ['Nature','Beaches','History','Temples','Adventure','Wildlife','Food','Shopping','Photography','Culture','Relaxation','Family activities'];
const formatINR = (value: number) => `₹${Math.round(value).toLocaleString('en-IN')}`;
const externalMap = (query: string) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
const datePlusDays = (date: string, days: number) => { if (!date) return ''; const parsed = new Date(`${date}T00:00:00Z`); if (Number.isNaN(parsed.getTime())) return ''; parsed.setUTCDate(parsed.getUTCDate() + days); return parsed.toISOString().slice(0, 10); };
const inclusiveDays = (start: string, end: string) => { const a = Date.parse(`${start}T00:00:00Z`); const b = Date.parse(`${end}T00:00:00Z`); return Number.isFinite(a) && Number.isFinite(b) && b >= a ? Math.floor((b - a) / 86_400_000) + 1 : null; };
const destinationById = (id: string) => destinations.find(item => item.id === id) || destinations[0];
function withTripTotal(plan: Itinerary, total: number, categories?: BudgetCategories): Itinerary {
  const safeTotal = Math.max(0, Math.round(total));
  const previous = plan.days.reduce((sum, day) => sum + Math.max(0, day.estimatedDailyCost), 0);
  let remaining = safeTotal;
  const days = plan.days.map((day, index) => {
    const amount = index === plan.days.length - 1 ? remaining : Math.round(previous > 0 ? safeTotal * Math.max(0, day.estimatedDailyCost) / previous : safeTotal / Math.max(1, plan.days.length));
    remaining -= amount;
    return { ...day, estimatedDailyCost: amount };
  });
  return { ...plan, days, estimatedTotal: safeTotal, ...(categories ? { budgetCategories: categories } : {}) };
}
const nearbyFor = (id: string) => {
  const groups: Record<string, string[]> = { mysuru: ['bengaluru','kabini'], coorg: ['mysuru','chikkamagaluru'], hampi: ['badami'], chikkamagaluru: ['coorg','shivamogga'], gokarna: ['udupi','shivamogga'], udupi: ['gokarna','shivamogga'], badami: ['hampi'], shivamogga: ['chikkamagaluru','gokarna'], bengaluru: ['mysuru'], kabini: ['mysuru','coorg'] };
  return (groups[id] || []).map(destinationById);
};
function ambitionWarnings(day: TripDay, days: TripDay[], routePreview: RoutePreview | null = null) {
  const warnings: string[] = [];
  const attractions = day.activities.filter(activity => activity.kind === 'attraction').length;
  const scheduledMinutes = day.activities.reduce((total, activity) => total + activity.durationMinutes, 0);
  const transferMinutes = routePreview ? Math.round(routePreview.totalDurationSeconds / 60) : 0;
  const spans = day.activities.filter(activity => /^\d{2}:\d{2}$/.test(activity.suggestedStartTime)).map(activity => { const [hours, minutes] = activity.suggestedStartTime.split(':').map(Number); const start = hours * 60 + minutes; return { start, end: start + activity.durationMinutes }; });
  const span = spans.length ? Math.max(...spans.map(item => item.end)) - Math.min(...spans.map(item => item.start)) : 0;
  let previousEnd = -1;
  for (const activity of day.activities) {
    const [hours, minutes] = activity.suggestedStartTime.split(':').map(Number);
    const start = hours * 60 + minutes;
    if (start < previousEnd) { warnings.push('Some stops overlap or appear out of order. Adjust their times or reorder them before travel.'); break; }
    previousEnd = start + activity.durationMinutes;
  }
  if (attractions > 2) warnings.push(`${attractions} sightseeing stops are planned. Consider removing one or two to leave time for breaks and local conditions.`);
  if (scheduledMinutes > 600 || span + transferMinutes > 720 || transferMinutes > 180) warnings.push(routePreview ? `Activities take about ${scheduledMinutes} minutes and the route adds about ${transferMinutes} minutes. Shorten the day or move a stop to another day.` : 'This schedule runs long before any uncalculated transfers. Shorten the day or move a stop to another day.');
  if (new Set(days.map(item => item.location.trim().toLowerCase())).size > 1) warnings.push('This itinerary changes destination area between days. No routing data is configured; check the cluster before travelling.');
  return warnings;
}

